import { Button as SpButton } from "@swc-react/button";
import "./styles.css";

interface ButtonProps extends React.ComponentProps<typeof SpButton> { }

export function Button(props: ButtonProps) {
  return (
    <SpButton
      {...props}
    />
  );
}

@layer serok {
  .serok-root sp-button {
    --spectrum-button-border-radius: var(--mod-button-border-radius,calc(var(--spectrum-button-height) / 4));
    &[variant="secondary"]:not([treatment="outline"]) {
      --mod-button-background-color-default: var(--spectrum-secondary-color-800);
      --mod-button-background-color-hover: var(--spectrum-secondary-color-900);
      --mod-button-background-color-down: var(--spectrum-secondary-color-900);
      --mod-button-background-color-key-focus: var(--spectrum-secondary-color-900);
      --mod-button-content-color-default: var(--white);
      --mod-button-content-color-hover: var(--white);
      --mod-button-content-color-down: var(--white);
      --mod-button-content-color-key-focus: var(--white);
    }
    &[variant="secondary"] {
      --mod-button-border-color-default: var(--spectrum-secondary-color-800);
      --mod-button-border-color-hover: var(--spectrum-secondary-color-900);
      --mod-button-border-color-down: var(--spectrum-secondary-color-900);
      --mod-button-border-color-key-focus: var(--spectrum-secondary-color-900);
      --mod-button-content-color-default: var(--spectrum-secondary-color-800);
      --mod-button-content-color-hover: var(--spectrum-secondary-color-900);
      --mod-button-content-color-down: var(--spectrum-secondary-color-900);
      --mod-button-content-color-key-focus: var(--spectrum-secondary-color-900);
      --mod-button-background-color-default: var(--white);
      --mod-button-background-color-hover: var(--spectrum-secondary-color-200);
      --mod-button-background-color-down: var(--spectrum-secondary-color-400);
      --mod-button-background-color-key-focus: var(--spectrum-secondary-color-200);
    }
  }
}
